def dedoublonne(valeurs):
    resultat = []
    vus = []
    for val in valeurs:
        if isinstance(val, list):
            cle = tuple(val)
        else:
            cle = val
        if cle not in vus:
            vus.append(cle)
            resultat.append(val)
    return resultat

def somme_pairs(nombres):
    if not nombres:
        return 0
    total = 0
    for n in nombres:
        if n % 2 == 0:
            total += n
    return total
